"// ==================== INTEGRASI CHATBOT: AI INSURANCE COACH ====================
let pdfDataCache = null;

async function loadPdfData() {
  if (pdfDataCache) return pdfDataCache;
  try {
    const res = await fetch("materi_pdf_text.json");
    if (!res.ok) throw new Error("Failed to load PDF database");
    pdfDataCache = await res.json();
    return pdfDataCache;
  } catch (err) {
    console.error("Error loading PDF text cache:", err);
    return null;
  }
}

function searchPdfContext(query, chunks, topN = 4) {
  if (!chunks || chunks.length === 0) return "";

  const stopwords = ["dan", "atau", "di", "ke", "dari", "yang", "untuk", "dengan", "pada", "adalah", "ini", "itu", "saya", "anda", "kami", "mereka", "dia"];
  const words = query.toLowerCase()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, "")
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopwords.includes(w));

  if (words.length === 0) {
    words.push(query.toLowerCase());
  }

  const scoredChunks = chunks.map(chunk => {
    let score = 0;
    const textLower = chunk.text.toLowerCase();

    // Exact phrase match bonus
    if (textLower.includes(query.toLowerCase())) {
      score += 30;
    }

    // Keyword match
    words.forEach(word => {
      if (textLower.includes(word)) {
        score += 5;
        const regex = new RegExp(word.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&'), 'gi');
        const matches = textLower.match(regex);
        if (matches) {
          score += matches.length * 2;
        }
      }
    });

    return { chunk, score };
  });

  const relevant = scoredChunks
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);

  if (relevant.length === 0) {
    return "";
  }

  return relevant.map(item => `[Sumber: ${item.chunk.source}, Halaman: ${item.chunk.page}]\n${item.chunk.text}`).join("\n\n---\n\n");
}

