"function formatTextMarkdown(text) {
  if (!text) return "";

  // Format headings: ### Heading to <h3>Heading</h3>
  let lines = text.split('\n');
  let formattedLines = lines.map(line => {
    let trimmed = line.trim();
    if (trimmed.startsWith('###')) {
      return `<h3>${trimmed.substring(3).trim()}</h3>`;
    }
    if (trimmed.startsWith('##')) {
      return `<h2>${trimmed.substring(2).trim()}</h2>`;
    }
    if (trimmed.startsWith('#')) {
      return `<h1>${trimmed.substring(1).trim()}</h1>`;
    }
    if (trimmed.startsWith('*') && !trimmed.startsWith('**')) {
      const content = trimmed.substring(1).trim();
      return `• ${content}`;
    }
    if (trimmed.startsWith('-')) {
      const content = trimmed.substring(1).trim();
      return `• ${content}`;
    }
    return line;
  });

  let formatted = formattedLines.join('\n');

  // Bold **text** to <strong>text</strong>
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  // Replace newlines with <br> to render correctly in HTML
  formatted = formatted.replace(/\n/g, '<br>');

  return formatted;
}"

