"function renderShopCatalog() {
  const container = document.getElementById("rewards-shop-grid");
  container.innerHTML = "";

  const shopItems = appState.shopItems;
  const p = appState.progress;

  shopItems.forEach(item => {
    const isOwned = p.rewardsOwned.includes(item.id);
    const card = document.createElement("div");
    card.className = `shop-card ${isOwned ? 'owned' : ''}`;

    let btnText = "Tukarkan";
    let btnDisabled = "";

    if (isOwned) {
      btnText = "Dimiliki";
      btnDisabled = "disabled";
    } else if (p.coins < item.price) {
      btnText = "Koin Tidak Cukup";
      btnDisabled = "disabled";
    }

    card.innerHTML = `
      <div class="shop-card-icon ${item.icon}">${getShopItemEmoji(item.icon)}</div>
      <h4>${item.name}</h4>
      <p>${item.desc}</p>
      <div class="shop-price-badge">🪙 ${item.price} Koin</div>
      <button class="btn-buy-item" ${btnDisabled} onclick="buyShopItem('${item.id}')">
        ${btnText}
      </button>
    `;
    container.appendChild(card);
  });
}"

