"function confirmPurchaseRewardItem() {
  const p = appState.progress;
  const item = appState.shopItems.find(i => i.id === selectedShopItemId);

  if (!item) return;

  if (p.coins < item.price) {
    showToast("Koin Anda tidak mencukupi untuk melakukan penukaran reward ini.", "error");
    hideShopConfirmModal();
    return;
  }

  // Kurangi koin
  p.coins -= item.price;
  p.rewardsOwned.push(item.id);

  // Jika beli bingkai emas, langsung pasang
  if (item.id === "gold_profile") {
    applyUserProfileGoldFrame();
  }

  // Catat transaksi penukaran reward ke localStorage
  const transaction = {
    id_transaksi: Date.now(),
    nama_agen: currentUser.name,
    nama_reward: item.name,
    harga_koin: item.price,
    tanggal: new Date().toLocaleString("id-ID"),
    status: (item.id === "gold_profile" || item.id === "streak_freeze" || item.id === "infinite_ai") ? "Otomatis" : "Pending"
  };
  const riwayat = JSON.parse(localStorage.getItem("riwayat_penukaran_reward")) || [];
  riwayat.push(transaction);
  localStorage.setItem("riwayat_penukaran_reward", JSON.stringify(riwayat));

  saveAgentProgress();
  showToast(`Sukses menukarkan koin! Item ${item.name} telah aktif.`, "success");
  logAdminActivity(`Agen ${currentUser.name} menukar reward virtual: ${item.name}`);

  hideShopConfirmModal();

  // Re-render
  updateTopGamifyBar();
  renderShopCatalog();
  renderLeaderboard();
  if (typeof renderTrainerClaimsTable === "function") {
    renderTrainerClaimsTable();
  }
}"

