"function switchTrainerTab(tabId) {
  currentTrainerTab = tabId;
  const tabs = document.querySelectorAll(".trn-content");
  tabs.forEach(t => t.classList.remove("active"));

  const tabBtns = document.querySelectorAll(".trn-tab-btn");
  tabBtns.forEach(btn => btn.classList.remove("active"));

  document.getElementById(tabId).classList.add("active");

  const matchedBtn = Array.from(tabBtns).find(btn => btn.getAttribute("onclick").includes(tabId));
  if (matchedBtn) matchedBtn.classList.add("active");

  if (tabId === "trn-material-mgmt") {
    renderTrainerMaterialsTable();
  } else if (tabId === "trn-progress-report") {
    renderTrainerProgressReport();
  } else if (tabId === "trn-reward-mgmt") {
    renderTrainerClaimsTable();
  }
}"

