"// Render tabel daftar klaim hadiah agen
function renderTrainerClaimsTable() {
  const tbody = document.getElementById("trainer-claims-rows");
  if (!tbody) return;

  tbody.innerHTML = "";
  const riwayat = JSON.parse(localStorage.getItem("riwayat_penukaran_reward")) || [];

  if (riwayat.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="5" style="text-align:center; padding: 40px 20px;">
          <div class="empty-state-claims" style="display:flex; flex-direction:column; align-items:center; gap:8px;">
            <span style="font-size: 40px; opacity: 0.25; filter: grayscale(100%); line-height: 1;">🎁</span>
            <span style="color: var(--text-muted); font-size: 13px; font-weight: 500;">Belum ada riwayat klaim hadiah.</span>
          </div>
        </td>
      </tr>
    `;
    return;
  }

  // Tampilkan riwayat (dari yang terbaru ke terlama)
  const sortedRiwayat = [...riwayat].reverse();

  sortedRiwayat.forEach(tx => {
    const tr = document.createElement("tr");

    let actionBtn = "";
    if (tx.status === "Pending") {
      actionBtn = `<button class="btn-read" onclick="processAgentReward(${tx.id_transaksi})">Proses Hadiah</button>`;
    } else {
      actionBtn = `<span style="color:var(--text-muted); font-size:11px;">Selesai diproses</span>`;
    }

    let statusClass = "belum";
    if (tx.status === "Otomatis" || tx.status === "Selesai") {
      statusClass = "selesai";
    }

    tr.innerHTML = `
      <td><strong>${tx.nama_agen}</strong></td>
      <td>${tx.nama_reward} <small style="display:block; color:var(--text-muted);">🪙 ${tx.harga_koin} Koin</small></td>
      <td>${tx.tanggal}</td>
      <td><span class="status-indicator ${statusClass}">${tx.status}</span></td>
      <td>${actionBtn}</td>
    `;
    tbody.appendChild(tr);
  });
}"

